import csv,json,pathlib
OUT=pathlib.Path('A1/c1/part-3.stored.tsv')
HEADER=['id','decision','sentences','what_it_does','basis','reason']
rows=list(csv.DictReader(open('A1/in/part-3.tsv'),delimiter='\t'))
byid={r['id'].removeprefix('nixos-'):r for r in rows}
def add(id,d,s,w,b,r):
 existing={x['id'] for x in csv.DictReader(OUT.open(),delimiter='\t')} if OUT.exists() else set()
 if not OUT.exists():
  with OUT.open('w') as f: csv.writer(f,delimiter='\t',lineterminator='\n').writerow(HEADER)
 if byid[id]['id'] in existing:return
 assert len(w.split())<=15,(id,w)
 assert len(r.split())<=30,(id,r)
 with OUT.open('a') as f:csv.writer(f,delimiter='\t',lineterminator='\n').writerow([byid[id]['id'],d,s,w,b,r]);f.flush()
def doc(id,d,s,w,url,r):add(id,d,s,w,'doc:'+url,r)
